INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.ba-sentence-basics.v1','hsk3-hsk1-2025-v6','GF0025-2021','3','2026.08.22-batch10','hskkit-editorial-batch10','HSKKit-original-editorial-v1','approved','published','The 把 sentence: object before the action','The 把 sentence: object before the action','n/a','Use 把 when a known object is changed, moved or otherwise affected.','grammar');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.comparison-with-bi.v1','hsk3-hsk1-2025-v6','GF0025-2021','2','2026.08.22-batch10','hskkit-editorial-batch10','HSKKit-original-editorial-v1','approved','published','Comparing with 比','Comparing with 比','n/a','Place 比 between the two things being compared.','grammar');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.morning-study-routine.v1','hsk3-hsk1-2025-v6','GF0025-2021','3','2026.08.22-batch10','hskkit-editorial-batch10','HSKKit-original-editorial-v1','approved','published','每天早上，林月先复习十个生词，再听十五分钟中文。她把不懂的句子写在本子上，晚上再看一遍。','每天早上，林月先复习十个生词，再听十五分钟中文。她把不懂的句子写在本子上，晚上再看一遍。','n/a','Every morning, Lin Yue reviews ten new words and listens to Chinese. She writes unfamiliar sentences down and reviews them at night.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.weekend-travel-plan.v1','hsk3-hsk1-2025-v6','GF0025-2021','2','2026.08.22-batch10','hskkit-editorial-batch10','HSKKit-original-editorial-v1','approved','published','王明周末想去杭州。火车比汽车快，也更准时。他决定星期六早上坐火车去，星期天下午回来。','王明周末想去杭州。火车比汽车快，也更准时。他决定星期六早上坐火车去，星期天下午回来。','n/a','Wang Ming chooses the train for a weekend trip because it is faster and more punctual.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.sentence.pronunciation-practice.v1','hsk3-hsk1-2025-v6','GF0025-2021','2','2026.08.22-batch10','hskkit-editorial-batch10','HSKKit-original-editorial-v1','approved','published','老师让我们练习发音。','老师让我们练习发音。','Lǎoshī ràng wǒmen liànxí fāyīn.','The teacher asks us to practise pronunciation.','sentence');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.basic-shi-negation.v1','hsk3-hsk1-2025-v6','GF0025-2021','1','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','Affirming and negating identity with 是','Affirming and negating identity with 是','n/a','Use 是 to connect identity and 不是 to negate it.','grammar');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.condition-with-zhiyao.v1','hsk3-hsk1-2025-v6','GF0025-2021','4','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','Stating a sufficient condition with 只要…就…','Stating a sufficient condition with 只要…就…','n/a','Use 只要 for a sufficient condition and 就 for its result.','grammar');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.contrast-with-jinguan.v1','hsk3-hsk1-2025-v6','GF0025-2021','5','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','Conceding with 尽管…但是…','Conceding with 尽管…但是…','n/a','Acknowledge a fact before introducing a contrasting outcome.','grammar');
