INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.grammar.advanced-concession-guran.v1','hsk3-hsk1-2025-v6','GF0025-2021','7-9','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','Evaluating concession with 固然…然而…','Evaluating concession with 固然…然而…','n/a','Grant a limited point before introducing the decisive qualification.','grammar');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.family-weekend-plan.v1','hsk3-hsk1-2025-v6','GF0025-2021','1','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','星期六，妈妈去商店，爸爸在家做饭。我和姐姐下午去公园。','星期六，妈妈去商店，爸爸在家做饭。我和姐姐下午去公园。','n/a','On Saturday, Mom goes to the store, Dad cooks at home, and my sister and I go to the park.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.library-evening-hours.v1','hsk3-hsk1-2025-v6','GF0025-2021','4','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','考试月期间，图书馆把闭馆时间从晚上九点延长到十一点。只要出示学生证，学生就可以进入夜间学习区。学校希望减少宿舍里的噪音，也让需要小组讨论的学生有合适的空间。','考试月期间，图书馆把闭馆时间从晚上九点延长到十一点。只要出示学生证，学生就可以进入夜间学习区。学校希望减少宿舍里的噪音，也让需要小组讨论的学生有合适的空间。','n/a','During exam month, the library extends its hours to reduce dorm noise and provide study space.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.flexible-work-schedule.v1','hsk3-hsk1-2025-v6','GF0025-2021','5','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','公司试行弹性工作制后，员工可以在早上七点到十点之间到岗。尽管个人时间更灵活，但是每个团队仍须保证核心时段有人值班。三个月后的调查显示，迟到减少了，跨部门会议却需要更早安排。','公司试行弹性工作制后，员工可以在早上七点到十点之间到岗。尽管个人时间更灵活，但是每个团队仍须保证核心时段有人值班。三个月后的调查显示，迟到减少了，跨部门会议却需要更早安排。','n/a','A flexible schedule reduced lateness but required earlier coordination for shared meetings.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.community-renewal-debate.v1','hsk3-hsk1-2025-v6','GF0025-2021','6','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','旧区改造方案提出增加公共绿地，并拆除部分路边停车位。支持者认为步行环境改善后，附近商店会获得更多客流；反对者则担心停车不便会使顾客转往别处。由于目前只有短期试点数据，委员会决定先延长观察期，再讨论是否全面实施。','旧区改造方案提出增加公共绿地，并拆除部分路边停车位。支持者认为步行环境改善后，附近商店会获得更多客流；反对者则担心停车不便会使顾客转往别处。由于目前只有短期试点数据，委员会决定先延长观察期，再讨论是否全面实施。','n/a','A committee extends observation because evidence on a contested renewal proposal is still short-term.','reading');
INSERT INTO content_assets (id,release_id,standard_version,level_band,content_version,source_ref,license_ref,qa_status,publish_status,hanzi,traditional,pinyin,meaning,part_of_speech) VALUES ('hsk3.reading.evidence-and-policy-evaluation.v1','hsk3-hsk1-2025-v6','GF0025-2021','7-9','2026.08.22-batch13','hskkit-editorial-batch13','HSKKit-original-editorial-v1','approved','published','一项试点报告称，新流程使平均办理时间缩短了百分之十五。这个结果固然值得重视，然而试点仅覆盖业务量较小的三个地区，而且没有说明复杂案件是否被排除。若直接把平均值视为普遍效果，可能掩盖不同地区之间的成本差异。因此，在扩大政策之前，评估者还应比较案件构成、执行成本与长期稳定性。','一项试点报告称，新流程使平均办理时间缩短了百分之十五。这个结果固然值得重视，然而试点仅覆盖业务量较小的三个地区，而且没有说明复杂案件是否被排除。若直接把平均值视为普遍效果，可能掩盖不同地区之间的成本差异。因此，在扩大政策之前，评估者还应比较案件构成、执行成本与长期稳定性。','n/a','Evaluators should test whether a limited pilot generalizes before expanding policy.','reading');
